package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
/** Detached perception and proposed actions. Only the authoritative director may turn a proposal into gameplay. */
public final class BotMessages {
    private BotMessages(){}
    public enum ActionKind {NONE,FIRE,RELOAD,MELEE,BUILD,BUILD_LINE,MINE,PLACE_PREFAB,DEPLOY,ORIENTED,PAINT,DISGUISE,MODE_COMMAND;public String code(){return name().toLowerCase(Locale.ROOT);}}
    public enum Priority {ROUTINE(10),TRAVERSAL(30),COMBAT(70),SURVIVAL(100);private final int value;Priority(int value){this.value=value;}public int value(){return value;}}
    public record Stock(int tool,int count){}public record Ammo(int tool,int clip,int reserve){}
    public record Player(int id,int generation,int team,int classId,boolean alive,boolean spawned,Vector position,Vector eye,Vector orientation,Vector velocity,int health,int tool,int blocks,int ammoClip,int ammoReserve,boolean bot,int weaponTool,List<Integer> loadout,List<String> prefabs,List<Stock> orientedStock,int carriedEntityId,int jetpackId,double jetpackFuel,boolean grounded,boolean wade,boolean reloading,String lastActionKind,boolean lastActionAccepted,Vector lastActionPosition,long lastActionFrame,double lastActionAt,double lastDamageAt,int lastDamageSourceId,Vector lastDamageSourcePosition,int lifeId,List<Stock> deployableStock,long lastActionRequestId,String lastActionReason,boolean lastTaskAccepted,double lastTaskAt,boolean canShoot,List<Ammo> weaponAmmo,boolean spawnProtected,int lastDamageKind,boolean canDig){
        public Player{loadout=List.copyOf(loadout);prefabs=List.copyOf(prefabs);orientedStock=List.copyOf(orientedStock);deployableStock=List.copyOf(deployableStock);weaponAmmo=List.copyOf(weaponAmmo);}
        public static Player basic(int id,int generation,int team,int classId,boolean alive,boolean spawned,Vector at,Vector eye,Vector aim,Vector velocity,int hp,int tool,int blocks,int clip,int reserve,boolean bot){return new Player(id,generation,team,classId,alive,spawned,at,eye,aim,velocity,hp,tool,blocks,clip,reserve,bot,-1,List.of(),List.of(),List.of(),-1,0,0,true,false,false,"",true,null,-1,0,0,-1,null,0,List.of(),0,"",true,0,true,List.of(),false,-1,true);}
    }
    public record Entity(int id,int type,int team,int ownerId,Vector position,boolean alive,String kind,int toolId,Vector velocity,double blastRadius,double detonateAt,boolean hazardous,int usesRemaining,Vector hitPosition,double hitRadius){}
    public record Objective(String kind,int team,Vector position,int carrierId,int state,List<Integer> bounds,List<Cell> cells,List<Cell> repairCells,double progress,int attacker,double expiresIn){public Objective{bounds=List.copyOf(bounds);cells=List.copyOf(cells);repairCells=List.copyOf(repairCells);}}
    public record Perception(long frameId,long mapEpoch,long modeEpoch,long topologyVersion,int observerId,int observerGeneration,double createdAt,String mode,List<Player> players,BotProfile profile,List<Entity> entities,List<Objective> objectives,List<Stimulus> stimuli,String modePhase,String behaviorVersion,boolean friendlyMischief,boolean localSafetyComplete,Map<String,Object> fun){
        public Perception{players=List.copyOf(players);entities=List.copyOf(entities);objectives=List.copyOf(objectives);stimuli=List.copyOf(stimuli);fun=freeze(fun);}
        public Perception withTopology(long version){return new Perception(frameId,mapEpoch,modeEpoch,version,observerId,observerGeneration,createdAt,mode,players,profile,entities,objectives,stimuli,modePhase,behaviorVersion,friendlyMischief,localSafetyComplete,fun);}
        public static Perception basic(long frameId,long epoch,long version,int observer,int generation,double now,List<Player> players){return new Perception(frameId,epoch,0,version,observer,generation,now,"tdm",players,null,List.of(),List.of(),List.of(),"","classic",true,true,Map.of());}
    }
    public record Movement(Vector direction,boolean jump,boolean crouch,boolean sneak,boolean sprint,Affordance affordance,boolean jetpackThrust,Vector travelSource,Vector travelWaypoint,Vector gazeWaypoint,int walkDrop){public static Movement still(){return new Movement(new Vector(0,0,0),false,false,false,false,Affordance.WALK,true,null,null,null,1);}}
    public record Look(Vector target,boolean visible,int targetPlayerId,int targetGeneration,double aimOffsetZ,boolean glance){}
    public record Action(ActionKind kind,int toolId,Vector position,Vector endPosition,String argument,int face,double yaw,int burst,double burstPause,long requestId){public static Action none(){return new Action(ActionKind.NONE,-1,null,null,"",-1,0,0,0,0);}}
    public record Diagnostic(String key,Object value){public Diagnostic{value=immutable(value,0);}}
    public record Intent(int botId,int botGeneration,long frameId,long mapEpoch,long modeEpoch,long topologyVersion,double createdAt,double expiresAt,Movement movement,Look look,int toolId,Action action,Priority priority,boolean secondaryFire,boolean zoom,Vector debugGoal,List<Vector> debugPath,String debugRole,int lifeId,List<Diagnostic> debugNavigation){public Intent{debugPath=List.copyOf(debugPath);debugNavigation=List.copyOf(debugNavigation);}}
    @SuppressWarnings("unchecked") public static Map<String,Object> freeze(Map<String,?> input){return (Map<String,Object>)immutable(input,0);}
    private static Object immutable(Object value,int depth){if(depth>32)throw new IllegalArgumentException("Bot data nesting bound");if(value==null||value instanceof String||value instanceof Integer||value instanceof Long||value instanceof Short||value instanceof Byte||value instanceof Double||value instanceof Float||value instanceof java.math.BigInteger||value instanceof java.math.BigDecimal||value instanceof Boolean||value instanceof Vector)return value;if(value instanceof Map<?,?> map){if(map.size()>4096)throw new IllegalArgumentException("Bot map bound");var result=new LinkedHashMap<String,Object>();for(var e:map.entrySet()){if(!(e.getKey() instanceof String key))throw new IllegalArgumentException("Bot map keys must be strings");result.put(key,immutable(e.getValue(),depth+1));}return Collections.unmodifiableMap(result);}if(value instanceof List<?> list){if(list.size()>4096)throw new IllegalArgumentException("Bot list bound");var result=new ArrayList<Object>();for(var item:list)result.add(immutable(item,depth+1));return Collections.unmodifiableList(result);}throw new IllegalArgumentException("Mutable/unsupported bot message value");}
}
